import{_ as a,o as s,c as e,a2 as t}from"./chunks/framework.DTdEDYjJ.js";const k=JSON.parse('{"title":"自托管应用授权","description":"","frontmatter":{},"headers":[],"relativePath":"guide/app-authorizations.md","filePath":"guide/app-authorizations.md"}'),o={name:"guide/app-authorizations.md"};function n(p,i,h,d,l,r){return s(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="自托管应用授权" tabindex="-1">自托管应用授权 <a class="header-anchor" href="#自托管应用授权" aria-label="Permalink to &quot;自托管应用授权&quot;">​</a></h1><p>0.10.9 开发源码新增 Node 应用授权服务的首版：拥有者集中连接应用，按 Bot 分配只读动作，服务端保存授权凭据并代为调用。首个提供商为 GitHub；这不是已经上线的官方多租户云服务。</p><h2 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h2><p>在自己的 Node 安全配置 <code>OPENBOT_KEYS_PASSPHRASE</code>，并为专用 GitHub OAuth App 配置 <code>OPENBOT_GITHUB_CLIENT_ID</code>、启用 Device Flow。直接运行 Node 时使用 <code>--with-integrations</code> 开启已有外部 Bot 入口；Docker 部署可设置 <code>OPENBOT_WITH_INTEGRATIONS=1</code>。Node 仍需配置有效 Bot、模型与入口调用权限。</p><p>应用授权仓独立于模型 Key 和 CLI 登录。它不会扫描或上传 Codex、Claude 等本地智能体的订阅信息。没有主口令时授权服务关闭，不阻止 Node 其他能力；没有 Client ID 时不能开始 OAuth。</p><h2 id="连接并分配" tabindex="-1">连接并分配 <a class="header-anchor" href="#连接并分配" aria-label="Permalink to &quot;连接并分配&quot;">​</a></h2><p>CLI 调用正在运行的 Node，公网用 HTTPS，SSH 本地转发可用环回 HTTP。通过自己的安全方式设置 <code>OPENBOT_NODE_TOKEN</code>，它是节点拥有者凭据：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OPENBOT_NODE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:14718</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node/app-authorizations-cli.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node/app-authorizations-cli.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;我的 GitHub&#39;</span></span></code></pre></div><p>命令显示 GitHub 官方验证地址与短码，由用户本人在浏览器确认。完成后默认不分配给任何 Bot。用实际连接 ID 和已有 Bot ID 替换以下占位符：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node/app-authorizations-cli.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grant</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CONNECTION_ID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BOT_ID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --actions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github.profile.read,github.repos.list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node/app-authorizations-cli.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CONNECTION_ID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BOT_ID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --actions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github.profile.read</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node/app-authorizations-cli.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revoke</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CONNECTION_ID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BOT_ID</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node/app-authorizations-cli.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span></span></code></pre></div><p><code>call</code> 是拥有者 act-as 验证；真实 Node 外部会话的 Bot 使用 <code>app_connections_list</code> 和 <code>app_connection_call</code>，身份来自可信运行上下文。只有获准的动作可调用，模型不接触 Token，也不能创建或扩大授权。该真实工具入口当前仅限已开启原工具权限的主Bot，且来源非Hub；应用grant不会自动开工具权限。其他入口、非主Bot外部会话、普通 Mac 聊天和浏览器任务尚未接入这些工具，桌面授权面板仍待实现。</p><h2 id="已验证的真实调用" tabindex="-1">已验证的真实调用 <a class="header-anchor" href="#已验证的真实调用" aria-label="Permalink to &quot;已验证的真实调用&quot;">​</a></h2><p>2026-10-20，本机独立 Node 已通过真实 GitHub Device Flow、身份读取、加密保存与正常重启读取。用户本人确认 <code>read:user</code>；完成连接时默认没有 Bot 授权。</p><p>云端 0.10.9 的默认主 Bot 随后通过实际 SDK stdio MCP 客户端完成 <code>app_connections_list</code> → <code>app_connection_call</code> → <code>github.profile.read</code>，读回 GitHub 真实身份资料。按 Bot 分配指定只读动作、撤销后拒绝调用的边界已验证。此处是真实 Bot 工具链，不以 CLI 的拥有者 act-as 调用代替。</p><p>该次调用审计为 <code>actor=bot</code>、<code>kind=call</code>、<code>status=completed</code>，并关联实际运行来源。成功后云 Node 与微信接收器正常重启，连接、Bot 授权、审计和外部任务状态保持。实际 MCP 客户端重交相同逻辑 <code>request_id</code> 时返回 <code>duplicate=true</code> 及原任务结果，没有新增 GitHub 调用；未确认的调用仍不自动重放。</p><p>GitHub 配额耗尽曾返回 <code>403</code>，该次调用如实失败，没有自动换号重试。配额恢复后显式发起新请求，才读回真实结果。任务标为 <code>done</code> 与应用调用成功分别核对；验证应用动作应同时查看工具结果和调用审计，不能只看主脑文字或任务状态。</p><p>本次云闭环只覆盖 GitHub 只读身份。它不代表 Mac 安装包已包含授权面板，也不代表自动 refresh、72 小时常驻、手机 App 公网 Hub 或新云双屏已验收。统一状态见<a href="/openbot/guide/status.html">支持范围</a>。</p><h2 id="撤销与运行边界" tabindex="-1">撤销与运行边界 <a class="header-anchor" href="#撤销与运行边界" aria-label="Permalink to &quot;撤销与运行边界&quot;">​</a></h2><p><code>disconnect CONNECTION_ID</code> 删除本节点活动 Token 和全部相关分配，不等于在 GitHub 撤销 Token。调用前后均核权限，撤销会中止在途调用并拒绝迟到结果；重启不自动重放未确认调用。OAuth 请求只有 <code>read:user</code>，实际仅提供身份与仓库列表两项只读动作，不支持任意请求或仓库写操作。</p><p>授权仓使用加密原子保存，目录0700、文件0600。它依赖单拥有者 Node 的实例锁和可信数据目录，不是多进程共享数据库。5000条常规审计满额后停止接新工作，保留止权空间；先导出审计，再显式使用 <code>audit-prune --through EVENT_ID</code> 清理。损坏或提交不明时封闭，不自动恢复旧授权。</p><p>本版尚未实现 refresh token 的保存和自动续期；access token过期时会明确要求重连。无需关闭GitHub的Token过期设置来迁就原型，长期自动刷新将在后续独立验收。</p><p>接口位于 <code>/api/v1/app-connections</code>，仅节点拥有者凭据可管理；旧凭据领取或外部入口令牌不能管理。源码测试使用自有夹具，与上面的真实 OAuth、云主 Bot 调用分别记录。桌面授权面板仍待实现。</p><p>完整命令、容量、API与恢复约束见源码 <code>docs/app-authorizations.md</code>。继续阅读<a href="/openbot/reference/node-api.html">Node API</a>、<a href="/openbot/reference/configuration.html">配置</a>和<a href="/openbot/deployment/self-host.html">部署</a>。GitHub 配置方式见<a href="https://docs.github.com/en/apps/oauth-apps/building-oauth-apps/authorizing-oauth-apps" target="_blank" rel="noreferrer">官方授权文档</a>。</p>`,23)])])}const F=a(o,[["render",n]]);export{k as __pageData,F as default};
